95	/**
96	 * Wrap every mention that is not in `known`, leaving code alone.
97	 *
98	 * `known` is compared case-insensitively, because GitHub logins are.
99	 */
100	export function escapeUnknownMentions(text: string, known: Iterable<string>): MentionCheck {
101	  const allowed = new Set([...known].map((login) => login.trim().toLowerCase()).filter(Boolean));
102	  const escaped: string[] = [];
103	
104	  const transform = (segment: string): string =>
105	    segment.replace(MENTION, (whole, before: string, login: string) => {
106	      if (allowed.has(login.toLowerCase())) return whole;
107	      if (!escaped.includes(login)) escaped.push(login);
108	      return `${before}\`@${login}\``;
109	    });
110	
111	  // Walk the code spans and transform only what lies between them.
112	  let out = "";
113	  let last = 0;
114	  CODE.lastIndex = 0;
115	  for (const match of text.matchAll(CODE)) {
116	    const at = match.index ?? 0;
117	    out += transform(text.slice(last, at));
118	    out += match[0];
119	    last = at + match[0].length;
120	  }
121	  out += transform(text.slice(last));
122	
123	  return { text: out, escaped };
124	}
